        1: {'id': 1, 'name': 'Alice'},
        2: {'id': 2, 'name': 'Bob'},
        3: {'id': 3, 'name': 'Charlie'}
    }
    return jsonify(users.get(user_id, {'error': 'User not found'})), 200 if user_id in users else 404

@users_bp.route('', methods=['POST'])
